package i18n

// Playbooks y lista de lectura (internal/playbook): comandos rechazados y errores de los archivos YAML. Los
// comandos y los nombres de archivo son datos.
func init() {
	e := func(es, en string, args ...string) entry { return entry{Es: es, En: en, Args: args} }
	add(map[string]entry{
		"playbook.err.denied":           e("playbook: comando no permitido en una recolección (solo lectura)", "playbook: command not allowed in a collection (read-only)"),
		"playbook.err.denied_cmd":       e("playbook: comando no permitido en una recolección (solo lectura): {cmd:q} ({cause})", "playbook: command not allowed in a collection (read-only): {cmd:q} ({cause})", "cmd", "cause"),
		"playbook.why.ascii":            e("solo ASCII imprimible; un retorno de carro o un carácter de 8 bits ejecutaría otro comando", "printable ASCII only; a carriage return or an 8-bit character would run another command"),
		"playbook.why.to_file":          e("to-file escribe en el equipo", "to-file writes to the device"),
		"playbook.why.probe":            e("ping y traceroute solo admiten destino y opciones acotadas (repeat ≤ 10, size ≤ 1500, timeout 1-10, source, vrf, ttl, probe)", "ping and traceroute only accept a destination and bounded options (repeat ≤ 10, size ≤ 1500, timeout 1-10, source, vrf, ttl, probe)"),
		"playbook.why.terminal":         e("solo terminal length y terminal width", "only terminal length and terminal width"),
		"playbook.why.not_read":         e("no es un comando de lectura", "not a read command"),
		"playbook.why.empty_pipe":       e("pipe vacío", "empty pipe"),
		"playbook.why.remote":           e("ruta remota (ftp:, tftp:, http:, scp:…): el equipo se conectaría a otro servidor", "remote path (ftp:, tftp:, http:, scp:…): the device would connect to another server"),
		"playbook.why.local_path":       e("ruta del equipo (disk0:, flash:, system:…): show escribiría o leería archivos locales", "device path (disk0:, flash:, system:…): show would write or read local files"),
		"playbook.why.pipe_sink":        e("redirect, tee y append escriben fuera de la sesión", "redirect, tee and append write outside the session"),
		"playbook.why.pipe_filter":      e("solo include, exclude, begin, section y count tras |", "only include, exclude, begin, section and count after |"),
		"playbook.why.redirect":         e("«>» no se permite en ningún lugar del comando, tampoco dentro de un filtro (como «| include ->»): «>» y «>>» redirigen la salida a un archivo del equipo; quita el carácter y, para filtrar, usa un patrón sin «>»", "\">\" is not allowed anywhere in the command, not even inside a filter (as in \"| include ->\"): \">\" and \">>\" redirect output to a file on the device; remove the character and, to filter, use a pattern without \">\""),
		"playbook.why.chain":            e("«;» no se permite en ningún comando: en NX-OS encadena comandos y cada parte se ejecuta; manda un comando por línea", "\";\" is not allowed in any command: on NX-OS it chains commands and every part runs; send one command per line"),
		"playbook.why.nxos_shell":       e("en NX-OS no se permiten paréntesis, «*», «[», llaves (salvo las de los datos del playbook) ni comillas antes del primer «|»: un shell podría interpretarlos; escribe el show sin ellos y, si filtras, pon el patrón entre comillas después del «|»", "on NX-OS parentheses, \"*\", \"[\", braces (except those of playbook data) and quotes before the first \"|\" are not allowed: a shell could interpret them; write the show without them and, if you filter, quote the pattern after the \"|\""),
		"playbook.why.shell":            e("«?» (pide ayuda al equipo y cambia el comando), «&», «&&», «||» y «<» (y en NX-OS también «$», «!», «\\» y «'») no se permiten en ningún comando (un shell los interpretaría y ejecutaría otra cosa), tampoco dentro de un filtro: quítalos y, para filtrar, usa un patrón sin esos caracteres", "\"?\" (asks the device for help and changes the command), \"&\", \"&&\", \"||\" and \"<\" (and on NX-OS also \"$\", \"!\", \"\\\" and \"'\") are not allowed in any command (a shell would interpret them and run something else), not even inside a filter: remove them and, to filter, use a pattern without those characters"),
		"playbook.why.subst":            e("«`» y «$(» no se permiten en ningún comando (sustituyen texto en el equipo y ejecutarían otra cosa), y en NX-OS tampoco las variables «$»: escribe el valor literal", "\"`\" and \"$(\" are not allowed in any command (they substitute text on the device and would run something else), and on NX-OS neither are \"$\" variables: write the literal value"),
		"playbook.why.quote":            e("comillas dobles sin cerrar o fuera de lugar (solo abren al inicio de una palabra y cierran antes de un espacio, «|» o el fin): ciérralas o quítalas", "unclosed or misplaced double quote (they only open at the start of a word and close before a space, \"|\" or the end): close it or remove it"),
		"playbook.why.write_nxos":       e("binary, tar, compressed y gzip hacen que show tech-support escriba en el equipo", "binary, tar, compressed and gzip make show tech-support write to the device"),
		"playbook.why.pipe_shell":       e("sed, awk, python, bash, run, source, tclsh, vsh, email, diff, less, xargs, perl, sscp, cut y tr (o su abreviatura) no son filtros de lectura: tras «|» usa include, exclude, begin, section o count; si tu patrón de include lleva «|» y lo que sigue se parece a uno de esos comandos, reescribe la alternancia", "sed, awk, python, bash, run, source, tclsh, vsh, email, diff, less, xargs, perl, sscp, cut and tr (or an abbreviation) are not read filters: after \"|\" use include, exclude, begin, section or count; if your include pattern has \"|\" and what follows looks like one of those commands, rewrite the alternation"),
		"playbook.why.pipe_filter_nxos": e("tras cada | solo include, exclude, begin, section, count, grep, egrep, head, last, wc, sort, uniq, json, json-pretty, xml, no-more o end (escritos completos; una alternancia va entre comillas dobles) con sus argumentos: sin ninguno en count, wc, no-more, json, json-pretty, xml, end, sort y uniq; un número en head y last; un patrón (y opciones de una lista cerrada) en include, exclude, begin, section, grep y egrep; nunca un archivo (bootflash:, volatile:, /ruta)", "after every | only include, exclude, begin, section, count, grep, egrep, head, last, wc, sort, uniq, json, json-pretty, xml, no-more or end (spelled out; an alternation goes in double quotes) with their arguments: none for count, wc, no-more, json, json-pretty, xml, end, sort and uniq; a number for head and last; a pattern (and options from a closed list) for include, exclude, begin, section, grep and egrep; never a file (bootflash:, volatile:, /path)"),
		"playbook.why.probe_nxos":       e("ping y traceroute de NX-OS: destino (que no sea una palabra clave) y opciones acotadas: vrf, source, source-interface y, solo en ping, count ≤ 10, packet-size ≤ 1500, timeout 1-10", "NX-OS ping and traceroute: a destination (not a keyword) and bounded options: vrf, source, source-interface and, ping only, count ≤ 10, packet-size ≤ 1500, timeout 1-10"),
		"playbook.why.show_file_asa":    e("en ASA, «file» tras show (show tech-support file disk0:x) escribe en el equipo", "on ASA, \"file\" after show (show tech-support file disk0:x) writes to the device"),
		"playbook.why.pipe_filter_asa":  e("tras | solo include, exclude, begin o grep (grep admite -v) y una expresión regular; lo que sigue es la regex y no puede empezar por redirect, tee ni append", "after | only include, exclude, begin or grep (grep accepts -v) and a regular expression; what follows is the regex and cannot start with redirect, tee or append"),
		"playbook.why.probe_asa":        e("ASA ping: [IFNAME] DESTINO [repeat 1-10] [timeout 1-10] [size 28-1500], o ping tcp [IFNAME] DESTINO PUERTO [count 1-10] [timeout 1-10]; traceroute: DESTINO [source IFNAME|IP] [numeric] [timeout 1-10] [probe 1-5] [use-icmp]; destino IP literal o nombre simple, nunca difusión, multicast, link-local ni sin especificar; opciones sin repetir", "ASA ping: [IFNAME] DEST [repeat 1-10] [timeout 1-10] [size 28-1500], or ping tcp [IFNAME] DEST PORT [count 1-10] [timeout 1-10]; traceroute: DEST [source IFNAME|IP] [numeric] [timeout 1-10] [probe 1-5] [use-icmp]; destination a literal IP or simple name, never broadcast, multicast, link-local or unspecified; options without repeating"),
		"playbook.why.tracer_asa":       e("ASA packet-tracer: input IFNAME (tcp o udp) SRC SPORT DST DPORT [detailed|xml] o input IFNAME icmp SRC TIPO CODIGO DST [detailed|xml], con IP literales; nada más (transmit, persist, vlan-id, destinos de archivo)", "ASA packet-tracer: input IFNAME (tcp or udp) SRC SPORT DST DPORT [detailed|xml] or input IFNAME icmp SRC TYPE CODE DST [detailed|xml], with literal IPs; nothing else (transmit, persist, vlan-id, file destinations)"),
		"playbook.why.terminal_asa":     e("en ASA solo «terminal pager N» y «terminal width N»", "on ASA only \"terminal pager N\" and \"terminal width N\""),
		"playbook.why.pipe_aireos":      e("AireOS no tiene pipe ni «?»; para filtrar usa grep include|exclude \"patrón\" \"show …\"", "AireOS has no pipe or \"?\"; to filter use grep include|exclude \"pattern\" \"show ...\""),
		"playbook.why.grep_aireos":      e("en AireOS solo grep include|exclude \"patrón\" \"show …\" (comillas dobles, sin comillas anidadas ni nada después) y el comando citado debe ser un show permitido", "on AireOS only grep include|exclude \"pattern\" \"show ...\" (double quotes, no nested quotes, nothing after) and the quoted command must be an allowed show"),
		"playbook.why.confirm_aireos":   e("el comando o su «y»/«n» final contesta una pregunta de confirmación (show run-config pregunta y/N)", "the command or its trailing \"y\"/\"n\" answers a confirmation question (show run-config asks y/N)"),
		"playbook.why.probe_aireos":     e("AireOS ping: IP [count 1-10] [size 1-1500], sin repetir opciones; nunca difusión, multicast, link-local ni sin especificar", "AireOS ping: IP [count 1-10] [size 1-1500], no repeated options; never broadcast, multicast, link-local or unspecified"),
		"playbook.why.show_ise":         e("en ISE, show no admite «?», «tail» (sigue el archivo y no termina), «file» (escribe en el nodo), «show top» (continuo) ni «show repository NOMBRE» (el nodo se conecta al repositorio), ni sus abreviaturas (tail y file desde 1 letra); para ver el final de un log usa «| last N»", "on ISE, show does not accept \"?\", \"tail\" (follows the file and never ends), \"file\" (writes to the node), \"show top\" (continuous) or \"show repository NAME\" (the node connects to the repository), nor their abbreviations (tail and file from 1 letter); to see the end of a log use \"| last N\""),
		"playbook.why.pipe_ise":         e("tras una sola | solo include, exclude, begin o end con un patrón, count sin argumentos o last [N], sin segunda | ni rutas; ISE no permite redirect, tee ni append", "after a single | only include, exclude, begin or end with a pattern, count with no arguments or last [N], no second | and no paths; ISE does not allow redirect, tee or append"),
		"playbook.why.probe_ise":        e("ISE: ping DESTINO [pingcount 1-10] [packetsize 1-1500]; traceroute y nslookup solo DESTINO; destino IP literal o nombre simple, nunca difusión, multicast, link-local ni sin especificar", "ISE: ping DEST [pingcount 1-10] [packetsize 1-1500]; traceroute and nslookup only DEST; destination a literal IP or simple name, never broadcast, multicast, link-local or unspecified"),
		"playbook.why.terminal_ise":     e("en ISE solo «terminal length 0» (sin filtro), la que manda el driver para quitar la paginación", "on ISE only \"terminal length 0\" (no filter), the one the driver sends to turn off paging"),
		"playbook.why.cr_in_line":       e("retorno de carro dentro de la línea", "carriage return inside the line"),
		"playbook.err.file":             e("playbook {name}: {cause}", "playbook {name}: {cause}", "name", "cause"),
		"playbook.err.required":         e("id, platform y name son obligatorios", "id, platform and name are required"),
		"playbook.err.no_commands":      e("sin comandos", "no commands"),
		"playbook.err.platform":         e("plataforma desconocida {platform:q} en platforms de {cmd:q}", "unknown platform {platform:q} in platforms of {cmd:q}", "platform", "cmd"),
		"playbook.err.empty_command":    e("comando vacío", "empty command"),
		"playbook.err.text":             e("{field} lleva caracteres de control o de dirección (bidi) que cambian cómo se ve el texto", "{field} contains control or direction (bidi) characters that change how the text looks", "field"),
		"playbook.err.timeout":          e("timeout {timeout:q} inválido en {cmd:q}", "invalid timeout {timeout:q} in {cmd:q}", "timeout", "cmd"),
		"playbook.err.timeout_max":      e("timeout {timeout:q} de {cmd:q} pasa el máximo de {max}", "timeout {timeout:q} of {cmd:q} exceeds the maximum of {max}", "timeout", "cmd", "max"),
		"core.svc.shutdown_busy":        e("hay trabajo en curso, no se apaga: {work}", "work is running, not shutting down: {work}", "work"),
		"core.svc.shutdown_audit":       e("no se pudo auditar core.shutdown, el núcleo no se apaga: {err}", "core.shutdown could not be audited, the core is not shutting down: {err}", "err"),
		"sys.err.not_regular":           e("la ruta no es un archivo regular", "the path is not a regular file"),
		"sys.err.not_owner":             e("la carpeta {path} existe y no es del usuario que corre el núcleo", "the folder {path} exists and does not belong to the user running the core", "path"),
		"sys.err.wait_timeout":          e("el proceso no terminó en el plazo", "the process did not exit in time"),
		"adhoc.err.no_targets":          e("indica al menos un equipo", "specify at least one device"),
		"adhoc.err.max":                 e("adhoc: {n} comandos; el máximo es {max}. El tope es de diseño: cada comando es una ida y vuelta por equipo y un lote largo acapara la sesión del equipo; divide el lote en tandas de {max} comandos o menos y ejecútalas una tras otra", "adhoc: {n} commands; the maximum is {max}. The cap is by design: every command is a round trip per device and a long batch ties up the device session; split the batch into runs of {max} commands or fewer and run them one after another", "n", "max"),
		"adhoc.err.node_stopped":        e("el núcleo se detuvo con el lote en curso; vuelve a lanzarlo", "the core stopped with the batch in progress; launch it again"),
		"adhoc.err.no_dir":              e("el lote no conserva su carpeta de salida", "the batch no longer has its output folder"),
		"adhoc.rep.no_output":           e("SIN SALIDA: {note}", "NO OUTPUT: {note}", "note"),
		"adhoc.note.ambiguous":          e("ambiguo: otro comando del lote se enmascara igual y no se sabe de cuál es la salida", "ambiguous: another command in the batch is masked the same way, so the output cannot be attributed"),
		"adhoc.note.invalid":            e("comando inválido en el equipo", "command invalid on the device"),
		"adhoc.note.no_round":           e("equipo sin ronda", "device without a round"),
		"adhoc.note.device":             e("equipo {state}", "device {state}", "state"),
		"adhoc.rep.state_none":          e("sin salida", "no output"),
		"adhoc.rep.csv_header":          e("equipo,direccion,comando,estado,salida", "device,address,command,state,output"),
		"adhoc.rep.md_header":           e("| Equipo | Dirección | Comando | Estado | Salida |", "| Device | Address | Command | State | Output |"),
		"adhoc.rep.summary":             e("{n} {n|equipo|equipos}, {ok} con salida completa", "{n} {n|device|devices}, {ok} with complete output", "n", "ok"),
		"playbook.err.none":             e("playbook: no hay comandos", "playbook: there are no commands"),
	})
}
